def table(headers,rows):
    return '<div class="table-scroll"><table><thead><tr>'+''.join('<th scope="col">'+str(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
# All chart axes compare energies only; no adoption interpretation is inferred from energy.
def chart():
    left,right,top,bottom=65,860,42,300
    xx=lambda yr:left+(yr-2026)*(right-left)/14
    yy=lambda e:top+(-e/14)*(bottom-top)
    parts=['<svg viewBox="0 0 900 355" role="img" aria-labelledby="energy-title energy-desc"><title id="energy-title">Reported energy across years</title><desc id="energy-desc">Run 2 quantum expectation values and simulated annealing references for 2026 through 2040; Run 1 is a single point at 2033. Each year has a different Hamiltonian, so this is not an adoption measure.</desc>']
    for e in range(0,-15,-2):
        y=yy(e);parts.append(f'<line x1="{left}" x2="{right}" y1="{y}" y2="{y}" class="gridline"/><text x="52" y="{y+4}" text-anchor="end">{e}</text>')
    for yr in range(2026,2041,2):parts.append(f'<text x="{xx(yr)}" y="325" text-anchor="middle">{yr}</text>')
    for data,color,dash,label in [(q,'#167a70','','Run 2 QAOA'),(sa,'#b66b24','stroke-dasharray="7 5"','SA reference')]:
        pts=' '.join(f'{xx(y)},{yy(e)}' for y,e in data.items());parts.append(f'<polyline points="{pts}" fill="none" stroke="{color}" stroke-width="3" {dash}/>')
        for y,e in data.items():parts.append(f'<circle cx="{xx(y)}" cy="{yy(e)}" r="3.5" fill="{color}"><title>{label}, {y}: {e}</title></circle>')
    x,y=xx(2033),yy(-2.643);parts.append(f'<path d="M{x},{y-6} l6,6 l-6,6 l-6,-6 Z" fill="#8569ad"><title>Run 1 QAOA, 2033: −2.643</title></path>')
    parts.append('<text x="65" y="20">● Run 2 QAOA</text><text x="240" y="20">– – SA reference</text><text x="440" y="20">◆ Run 1 · 2033 only</text><text x="455" y="350" text-anchor="middle">Year · energy in model units</text></svg>')
    return ''.join(parts)
# Source appendices preserve the narratives, while replacing CDN charts with source-data tables.
def appendix(s,charts,run):
    s=BeautifulSoup(str(s),'html.parser')
    for idx,spec in enumerate(charts,1):
        node=s.select_one(f'#analysis-chart-{idx}')
        vals=spec['data']['values'];headers=list(vals[0]);node.clear();node.append(BeautifulSoup('<h4>'+html.escape(spec.get('title','Chart data'))+'</h4>'+table(headers,[[html.escape(str(v.get(k,''))) for k in headers] for v in vals]),'html.parser'))
    for script in s.find_all('script'):script.decompose()
    for el in s.body.find_all(True):
        if el.has_attr('id'):el['id']=f'run-{run}-'+el['id']
    return ''.join(str(x) for x in s.body.contents)
