css += """
.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:22px 0}.compare-grid .panel{margin:0}.state-map,.gap-map{min-width:370px}.state-map th,.gap-map th{font-size:12px;text-transform:none}.state-map td,.gap-map td{text-align:center;padding:9px;font-variant-numeric:tabular-nums}.state-map td:first-child,.gap-map td:first-child{text-align:left;background:var(--paper)!important;color:var(--ink)!important;font-weight:600}.status-digital{background:#bce1cd;color:#173e30}.status-paper{background:var(--soft);color:var(--muted)}.no-data{background:repeating-linear-gradient(135deg,var(--paper),var(--paper) 5px,var(--soft) 5px,var(--soft) 7px);color:var(--muted)}.map-legend{display:flex;gap:16px;flex-wrap:wrap;margin:12px 0;font-size:12px;color:var(--muted)}.map-legend span{display:flex;gap:6px;align-items:center}.map-legend i{display:inline-block;width:14px;height:14px}.delta-0{background:var(--soft);color:var(--muted)}.delta-1{background:#c7e1d9;color:#153e3c}.delta-2{background:#79b29f;color:#123b2d}.compare-grid h3{font-size:17px;margin:0 0 12px}.compare-grid p{font-size:13px}.matrix-note{font-size:12px;color:var(--muted)}@media(max-width:1100px){.compare-grid{grid-template-columns:1fr}}@media print{.compare-grid{grid-template-columns:1fr 1fr}.state-map,.gap-map{min-width:0}.state-map td,.gap-map td{font-size:8pt;padding:5px}}html[data-theme=dark] .status-digital{background:#285542;color:#e2f2e8}
"""
node_names=list(dict.fromkeys(d['industry'] for d in regional))
state_table='<div class="table-scroll"><table class="state-map" id="state-comparison"><caption>2033 digital/paper states reported by each 20-node quantum execution. These are report claims, not reconstructed measurement counts.</caption><thead><tr><th scope="col">Industry</th><th scope="col">Run 1</th><th scope="col">Run 2</th><th scope="col">Run 4</th></tr></thead><tbody>'
for name in node_names:
    digital=name in ['Technology','Media','Telecom','Retail','Hospitality']
    label='Digital' if digital else 'Paper'
    state_table+='<tr><td>'+name+'</td>'+''.join(f'<td class="status-{label.lower()}" title="Run {run}, {name}, 2033: reported {label.lower()}">{label}</td>' for run in [1,2,4])+'</tr>'
state_table+='</tbody></table></div>'
gap_lookup={1:{2033:2.467},2:{r['year']:r['absolute_gap'] for r in rows},4:{2033:2.437}}
max_gap=max(r['absolute_gap'] for r in rows)
gap_table='<div class="table-scroll"><table class="gap-map" id="gap-comparison"><caption>Mean-energy gap to the same-year SA reference, in model energy units. Smaller is better. Run 3 supplies no comparable energy values.</caption><thead><tr><th scope="col">Year</th>'+''.join(f'<th scope="col">Run {i}</th>' for i in [1,2,3,4])+'</tr></thead><tbody>'
for year in range(2026,2041):
    gap_table+=f'<tr><td>{year}</td>'
    for run in [1,2,3,4]:
        gap=gap_lookup.get(run,{}).get(year)
        if gap is None:gap_table+='<td class="no-data" title="No comparable quantum expectation supplied">—</td>'
        else:
            # Green to amber: one fixed, stated linear scale across all observations.
            t=gap/max_gap
            color=tuple(round(a+(b-a)*t) for a,b in zip((204,232,215),(229,170,111)))
            gap_table+=f'<td style="background:rgb{color};color:#23382f" title="Run {run}, {year}: gap {gap:.3f}">{gap:.3f}</td>'
    gap_table+='</tr>'
gap_table+='</tbody></table></div>'
comparison_section='''<section id="comparisons"><h2><span class="section-index">02</span>Compare the runs at a glance</h2><p>Compare the same model and year for quality; treat the larger regional model as a separate scenario. The maps below show exactly where evidence overlaps and where measurements are missing.</p>'''+table(['Run','Scope / execution','2033 QAOA expectation','2033 energy gap','Elapsed-time evidence'],[
['1 · Initial checkpoint','20 nodes; p=2; quantum test at 2033','−2.643','2.467','~10 min quantum turnaround'],['2 · Full sweep','20 nodes; p=2; 2026–2040 quantum sweep','−2.926','2.184','~5 min/year; 2033 ~8 min'],['3 · Regional scenario','100 nodes, 220 ties; classical annealing','Not supplied','Not supplied','~5 s for classical sweep'],['4 · Simulator repeat','20 nodes; 2033 repeated execution','−2.673','2.437','~8 min quantum turnaround']])+'''<div class="compare-grid"><div class="panel"><h3>Same reported answer at 2033</h3>'''+state_table+'''<div class="map-legend"><span><i class="status-digital"></i>Digital</span><span><i class="status-paper"></i>Paper</span></div><p>All three 20-node reports identify the same five digital industries. Run 3 is excluded here because it changes the scenario and has five regional states per industry.</p></div><div class="panel"><h3>How close is the quantum mean energy?</h3>'''+gap_table+f'''<p class="matrix-note">Green → amber: gap 0 → {max_gap:.3f}. Hatched “—” means not supplied, not zero. Only the 2033 row compares multiple executions of the same-year model. Across years, each Hamiltonian changes; this is not a pooled accuracy score.</p><p>Run 2 has the smallest gap at the shared checkpoint. Run 4 adds qualitative agreement, but does not improve on Run 2’s mean energy. Its table value is used despite the trace discrepancy documented below.</p></div></div><p class="source-note">Timing now comes from the supplemental ledger: approximate runtime/queue figures, not compute-only measurements. The speed section visualizes reported 2033 turnaround separately from classical sweep durations.</p></section>'''
sec.insert(1,comparison_section)

navnames=[('answers','The two answers'),('comparisons','Run heatmaps'),('quality','Solution quality'),('speed','Speed & scale'),('regions','Regional results'),('next','Next evidence'),('sources','All source reports')]
nav=''.join(f'<a href="#{id}"><span>{i:02}</span>{name}</a>' for i,(id,name) in enumerate(navnames,1))
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paper Phase Transition · Quality, Speed & Scale</title><style>'''+css+'''</style></head><body><a class="skip" href="#main">Skip to findings</a><header class="topbar"><div class="brand">Vasion / IQC 2026 · Consolidated findings</div><div class="tools"><button id="theme" aria-pressed="false">Dark mode</button><button id="print">Print / PDF</button></div></header><div class="layout"><aside><p>Four reports + runtime ledger</p><nav aria-label="Report sections">'''+nav+'''</nav><div class="side-note">Reported results.<br>Calculated comparisons.<br>Visible evidence gaps.</div></aside><main id="main"><header class="hero"><p class="eyebrow">Quality · Speed · Practical insight</p><h1>Good answers.<br>Fast enough?</h1><p class="subtitle">What four reports tell us about modeling the paper-to-digital transition.</p><div class="hero-stats"><div><strong>4</strong><span>reports consolidated</span></div><div><strong>20 → 100</strong><span>nodes explored</span></div><div><strong>1 → 5</strong><span>regions modeled</span></div></div></header>'''+''.join(sec)+'''<footer>Updated synthesis of Reports 1–4 plus the runtime ledger. Source reports preserved; numerical comparisons are derived from supplied data. No new solver jobs were run. This report does not establish forecast accuracy or quantum speedup.</footer></main></div><script>const theme=document.querySelector('#theme');theme.addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';theme.textContent=dark?'Light mode':'Dark mode';theme.setAttribute('aria-pressed',String(dark));});document.querySelector('#print').addEventListener('click',()=>window.print());</script></body></html>'''
out=ROOT/'consolidated-findings.html'
s=BeautifulSoup(page,'html.parser')
for number,section in enumerate(s.select('main > section'),1):
    index=section.select_one('h2 .section-index')
    if index:index.string=f'{number:02d}'
out.write_text(str(s))
